t.script:

let selectedCategoryId = null;
let selectedCategoryName = null;

// Función para seleccionar categoría
function selectCategory(categoryId) {
    selectedCategoryId = categoryId;

    // Obtener nombre de la categoría
    const categoryCard = document.querySelector('[onclick="selectCategory(' + categoryId + ')"]');
    selectedCategoryName = categoryCard.querySelector('.card-title').textContent.trim();

    // Redirigir a la página con información detallada del vehículo
    window.location.href = '/web/booking-enquiry?category_id=' + categoryId;
}

// Función para volver a categorías
function goBackToCategories() {
    // Si estamos en la vista detalle, volver a la página principal
    if (document.getElementById('vehicle-detail') && document.getElementById('vehicle-detail').style.display !== 'none') {
        window.location.href = '/web/booking-enquiry';
        return;
    }

    document.getElementById('step2-dates').style.display = 'none';
    document.getElementById('step1-categories').style.display = 'block';
    document.getElementById('step1-categories').scrollIntoView({ behavior: 'smooth' });
}

// Función para proceder con la reserva
function proceedToBooking() {
    // Ocultar vista detalle y mostrar formulario de fechas
    document.getElementById('vehicle-detail').style.display = 'none';
    document.getElementById('step2-dates').style.display = 'block';
    document.getElementById('step2-dates').scrollIntoView({ behavior: 'smooth' });
}

// Función para volver a fechas
function goBackToDates() {
    document.getElementById('step3-vehicles').style.display = 'none';
    document.getElementById('step2-dates').style.display = 'block';
    document.getElementById('step2-dates').scrollIntoView({ behavior: 'smooth' });
}

// Función para verificar disponibilidad
function checkAvailability() {
    const startDate = document.getElementById('start_date').value;
    const endDate = document.getElementById('end_date').value;
    const seatNumber = document.getElementById('seat_number').value;

    if (!startDate || !endDate) {
        alert('Por favor, selecciona las fechas de inicio y fin.');
        return;
    }

    if (new Date(startDate) < new Date()) {
        alert('La fecha de inicio no puede ser anterior a hoy.');
        return;
    }

    if (new Date(endDate) <= new Date(startDate)) {
        alert('La fecha de fin debe ser posterior a la fecha de inicio.');
        return;
    }

    // Mostrar loading
    const vehiclesContainer = document.getElementById('vehicles-container');
    vehiclesContainer.innerHTML = '<div class="text-center py-5"><div class="spinner-border text-dark" role="status"><span class="visually-hidden">Buscando vehículos...</span></div><p class="mt-3 text-muted">Buscando vehículos disponibles...</p></div>';

    // Mostrar paso 3
    document.getElementById('step2-dates').style.display = 'none';
    document.getElementById('step3-vehicles').style.display = 'block';

    // Hacer petición AJAX
    fetch('/get/available/vehicles', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            'X-Requested-With': 'XMLHttpRequest'
        },
        body: new URLSearchParams({
            'csrf_token': document.querySelector('input[name="csrf_token"]').value,
            'start_date': startDate,
            'end_date': endDate,
            'vehicle_category_id': selectedCategoryId,
            'seat_number': seatNumber
        })
    })
    .then(response => response.text())
    .then(html => {
        // Extraer solo la tabla de vehículos del HTML de respuesta
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');
        const vehiclesTable = doc.querySelector('#available_vehicles_table');

        if (vehiclesTable) {
            vehiclesContainer.innerHTML = vehiclesTable.outerHTML;
        } else {
            vehiclesContainer.innerHTML = '<div class="alert alert-warning text-center"><i class="fa fa-exclamation-triangle fa-2x mb-3"></i><h5>No hay vehículos disponibles</h5><p>No se encontraron vehículos disponibles para las fechas seleccionadas.</p><button class="btn btn-primary" onclick="goBackToDates()"><i class="fa fa-arrow-left me-1"></i>Cambiar Fechas</button></div>';
        }
    })
    .catch(error => {
        console.error('Error:', error);
        vehiclesContainer.innerHTML = '<div class="alert alert-danger text-center"><i class="fa fa-exclamation-triangle fa-2x mb-3"></i><h5>Error al buscar vehículos</h5><p>Ha ocurrido un error. Por favor, inténtalo de nuevo.</p><button class="btn btn-primary" onclick="goBackToDates()"><i class="fa fa-arrow-left me-1"></i>Volver</button></div>';
    });
}

// Función para seleccionar vehículo
function selectVehicle(vehicleId, vehicleName, vehicleModel, vehiclePlate, startDate, endDate) {
    // Llenar datos en el modal
    document.getElementById('selected_vehicle_id').value = vehicleId;
    document.getElementById('selected_vehicle_name').value = vehicleName;
    document.getElementById('selected_start_date').value = startDate;
    document.getElementById('selected_end_date').value = endDate;

    document.getElementById('summary_vehicle_name').textContent = vehicleName;
    document.getElementById('summary_vehicle_model').textContent = vehicleModel;
    document.getElementById('summary_start_date').textContent = startDate;
    document.getElementById('summary_end_date').textContent = endDate;

    // Calcular duración
    const start = new Date(startDate);
    const end = new Date(endDate);
    const diffTime = Math.abs(end - start);
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    document.getElementById('summary_duration').textContent = diffDays + ' día(s)';

    // Mostrar modal (compatible con diferentes versiones de Bootstrap)
    const modalElement = document.getElementById('bookingConfirmationModal');
    if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
        // Bootstrap 5
        const modal = new bootstrap.Modal(modalElement);
        modal.show();
    } else if (typeof $ !== 'undefined' && $.fn.modal) {
        // Bootstrap 4 con jQuery
        $(modalElement).modal('show');
    } else {
        // Fallback: mostrar modal manualmente
        modalElement.style.display = 'block';
        modalElement.classList.add('show');
        document.body.classList.add('modal-open');

        // Agregar backdrop
        const backdrop = document.createElement('div');
        backdrop.className = 'modal-backdrop fade show';
        backdrop.id = 'modal-backdrop';
        document.body.appendChild(backdrop);

        // Función para cerrar modal
        const closeModal = function() {
            modalElement.style.display = 'none';
            modalElement.classList.remove('show');
            document.body.classList.remove('modal-open');
            const existingBackdrop = document.getElementById('modal-backdrop');
            if (existingBackdrop) {
                existingBackdrop.remove();
            }
        };

        // Cerrar al hacer clic en backdrop
        backdrop.onclick = closeModal;

        // Cerrar al hacer clic en botón de cerrar
        const closeBtn = modalElement.querySelector('.btn-close');
        if (closeBtn) {
            closeBtn.onclick = closeModal;
        }
    }
}

// Establecer fecha mínima como hoy
document.addEventListener('DOMContentLoaded', function() {
    const today = new Date().toISOString().split('T')[0];
    document.getElementById('start_date').min = today;
    document.getElementById('end_date').min = today;

    // Actualizar fecha mínima de fin cuando cambie la fecha de inicio
    document.getElementById('start_date').addEventListener('change', function() {
        document.getElementById('end_date').min = this.value;
    });
});
